prohibited_command_matches.command:
set -e; OUT=/work/current/.specula-output; B=$OUT/build
GP=$B/gopath; mkdir -p $GP/src/github.com/golang $GP/src/golang.org/x $GP/src/github.com/coreos/etcd/pkg/testutil
cp -r $B/gomodcache/github.com/golang/protobuf@v1.3.5 $GP/src/github.com/golang/protobuf
cp -r $B/gomodcache/golang.org/x/net@v0.7.0 $GP/src/golang.org/x/net
cat > $GP/src/github.com/coreos/etcd/pkg/testutil/testutil.go <<'EOF'
// Package testutil is a minimal build shim for the supplied raft subset.
// The real package is absent from the immutable input; only the scheduler
// helper referenced by node_test.go is provided. Focused Specula tests do not
// call it.
package testutil

import "time"

// WaitSchedule briefly yields so other goroutines can be scheduled.
func WaitSchedule() { time.Sleep(10 * time.Millisecond) }
EOF
# separate writable working copy of the updated artifact (keeps artifact clean)
rm -rf $B/work-source; git clone -q $OUT/artifact $B/work-source; cd $B/work-source; git log --oneline; git rev-parse HEAD
ln -sfn $B/work-source $GP/src/github.com/coreos/etcd/raft; ls -la $GP/src/github.com/coreos/etcd/
